    add(g, new T.BoxGeometry(o.w + 0.08, 0.08, t + 0.08), k.chaperon, 0, o.h / 2 + 0.04, o.d / 2 - t / 2);
    for (const s of [-1, 1]) add(g, new T.BoxGeometry(t + 0.08, 0.08, o.d + 0.04), k.chaperon, s * (o.w / 2 - t / 2), o.h / 2 + 0.04, 0);
