        X -= Math.sign(X) * Math.max(0, bump) * (Math.abs(X) > hx - 0.08 ? 1 : 0); Z -= Math.sign(Z) * Math.max(0, bump) * (Math.abs(Z) > hz * w - 0.08 ? 1 : 0); if (Y > top - 0.05) Y -= Math.max(0, bump);
