    if (fig && fig.isSkinned) { const cx = fig.pose0 && fig.pose0.cx !== undefined ? fig.pose0.cx : 0.05; camera.position.set(cx, 1.0, 5.85); camera.lookAt(cx, 0.9, 0); } else { camera.position.set(0.25, 1.0, 5.5); camera.lookAt(0.05, 0.9, 0); }
