    $('#bannerText').textContent = txt; $('#bannerSub').textContent = r.reason;
    el.className = 'banner ' + (r.winner === 1 ? 'team1' : r.winner === 0 ? 'team0' : 'draw'); el.offsetWidth; el.classList.add('show');
