    const txt = window.HQ.exportSave(), name = 'operator-tactics-carriere.json';
    $('#setMsg').style.color = '';
    if (dl) { dl.save({ filename: name, data: txt }).then(() => { $('#setMsg').textContent = 'Carrière exportée.'; }, (e) => { $('#setMsg').textContent = e && e.code === 'declined' ? 'Export annulé.' : 'Export impossible ici.'; }); return; }
